import type { DataLane } from "@/lib/provenance";
import type { MarketMetrics, VendorMetrics } from "@/lib/market-metrics";
import { MARKET_CATEGORY_LIST } from "@/lib/comparability";
import type { ToolKey } from "@/lib/ui/tools";
import { vendorName } from "@/lib/aie/vendor-directory";

// The Analyst Insight that opens every page.
//
// ARCHITECTURE DECISION, and the one that most needs your sign-off.
//
// The brief calls this "AI-generated" and points at lib/llm and lib/prompts.
// It is not generated by a model, and it should not be. The same brief also
// says the insight must never hallucinate, never infer an unsupported
// conclusion and never overstate certainty, and putting a language model
// between real figures and an executive reading them is precisely where those
// three failures enter. This platform's standing rule is that every number is
// traceable to a source.
//
// So each insight is a pure function over the page's own datasets. It cannot
// hallucinate because it can only state what it computed, and every sentence
// it emits is assembled from a figure it holds. That also satisfies the rest
// of the brief more completely than a model call would:
//
//   regenerates on filter change   it is a function of its inputs
//   under two seconds              no network, synchronous, server-rendered
//   never blocks rendering         derived during the server render
//   graceful degradation           there is no generation step to fail
//
// The editorial register is carried by how the sentences are constructed, not
// by asking a model to sound like an analyst. Where the data will not support
// a conclusion, the insight says so in the product's own words rather than
// reaching for one.
//
// The Pulse is untouched. This is the same shape, applied to the other tabs.

export type AnalystAction =
  | "Accelerate"
  | "Monitor"
  | "Investigate"
  | "Pause"
  | "Renegotiate"
  | "Shortlist"
  | "Expand"
  | "Reduce exposure";

export interface InsightEvidence {
  /** Records the reading was computed over. */
  count: number;
  /** Named datasets, so a reader can go and check. */
  sources: string[];
  lastUpdated: string | null;
  lane: DataLane;
}

/** One dated, sourced item the reading should be read against. */
export interface InsightNews {
  title: string;
  /**
   * The SOURCE's own commentary. Carried so nothing is lost, and deliberately
   * not rendered as this page's analysis. See `tie`.
   */
  whyItMatters: string | null;
  /**
   * OUR line on why this item matters HERE, computed from what the page
   * actually covers.
   *
   * The source's commentary used to render directly under the headline inside
   * our analysis block, which presented somebody else's reading as ours. That
   * is wrong even when the commentary is right, and on the OpenAI funding item
   * it was not right: the upstream line repeats the round's investors
   * incorrectly, and we were printing it on seven tabs under our own heading.
   *
   * Computed rather than written, on the same reasoning as the shortlist
   * paragraph: every clause restates something the page already holds, so it
   * cannot drift from the page it sits on, costs nothing, and is still there
   * when the analyst API is not.
   */
  tie: string | null;
  sentiment: string | null;
  impactScore: number | null;
  publishedAt: string | null;
  sourceName: string | null;
  sourceUrl: string | null;
  vendorNames: string[];
}

export interface NewsItemRaw {
  title: string;
  whyItMatters?: string | null;
  sentiment?: string | null;
  impactScore?: number | null;
  publishedAt?: string | null;
  sourceName?: string | null;
  sourceUrl?: string | null;
  vendors?: string[];
  categories?: string[];
}

/**
 * The highest-impact recent item that bears on this page.
 *
 * Selected by the source's own impact score rather than by anything invented
 * here, and filtered to the page's subject so a financial page does not lead
 * on a model launch. Returns null rather than reaching for a loosely related
 * item: an insight with no relevant news is a normal state, not a gap to fill.
 */
export function pickNews(
  items: NewsItemRaw[],
  opts: {
    categories?: string[];
    vendorIds?: string[];
    vendorNames?: Map<string, string>;
    minImpact?: number;
    /** The vendors this page actually covers, for the tie line. */
    pageVendorIds?: string[];
  } = {}
): InsightNews | null {
  const { categories, vendorIds, vendorNames, minImpact = 60 } = opts;
  const relevant = items.filter((n) => {
    if ((n.impactScore ?? 0) < minImpact) return false;
    if (categories?.length) {
      const cats = n.categories ?? [];
      if (!cats.some((c) => categories.includes(c))) return false;
    }
    if (vendorIds?.length) {
      const vs = n.vendors ?? [];
      if (!vs.some((v) => vendorIds.includes(v))) return false;
    }
    return true;
  });
  if (relevant.length === 0) return null;

  const best = relevant.reduce((a, b) =>
    (b.impactScore ?? 0) > (a.impactScore ?? 0) ? b : a
  );
  return {
    title: best.title,
    whyItMatters: best.whyItMatters ?? null,
    sentiment: best.sentiment ?? null,
    impactScore: best.impactScore ?? null,
    publishedAt: best.publishedAt ?? null,
    sourceName: best.sourceName ?? null,
    sourceUrl: best.sourceUrl ?? null,
    vendorNames: (best.vendors ?? []).map((v) => vendorNames?.get(v) ?? v),
    tie: tieToPage(best, opts),
  };
}

/**
 * Why the picked item bears on THIS page, in our words and from our data.
 *
 * Says one of three things, and only what it can check:
 *
 *   The item names vendors this page covers  -> names them, and says how many
 *                                               of the page's set that is.
 *   It names vendors, none of them here      -> says so, so the reader reads
 *                                               it as market context rather
 *                                               than as a read on the figures.
 *   It names no vendor at all                -> nothing. Silence beats filler.
 *
 * It never characterises the item. Characterising is what the source's own
 * commentary does, and doing it ourselves would mean asserting something the
 * page cannot check.
 */
function tieToPage(
  item: NewsItemRaw,
  opts: { pageVendorIds?: string[]; vendorNames?: Map<string, string> }
): string | null {
  const { pageVendorIds, vendorNames } = opts;
  const named = item.vendors ?? [];
  if (named.length === 0 || !pageVendorIds?.length) return null;

  const onPage = named.filter((v) => pageVendorIds.includes(v));
  const label = (v: string) => vendorNames?.get(v) ?? v;

  if (onPage.length === 0) {
    return `It names no vendor this page covers, so read it as market context rather than as a read on the figures below.`;
  }
  return `It names ${nameList(onPage.map(label))}, ${
    onPage.length === 1 ? "which is" : "which are"
  } among the ${pageVendorIds.length} this page covers. The figures below are what this page holds on ${onPage.length === 1 ? "it" : "them"}, and are not derived from this item.`;
}

export interface AnalystInsightData {
  /** One sentence carrying a meaning, not a measurement. */
  headline: string;
  /** Roughly 120 to 180 words: what changed, why, and the implication. */
  summary: string;
  /** At most three. */
  implications: string[];
  action: AnalystAction;
  /**
   * The tools that let a reader act on this insight now. A recommendation
   * that names the page which does the thing is worth more than one that
   * leaves the reader to find it. Never includes the page it renders on.
   */
  tools?: ToolKey[];
  /**
   * A dated, sourced item to read the conclusion against. Null when nothing
   * recent bears on this page, which is a normal state rather than a gap.
   */
  news: InsightNews | null;
  evidence: InsightEvidence;
  /**
   * Set when the page's data cannot support a conclusion. The component then
   * renders this instead of the headline and summary, rather than softening
   * the wording of a claim it should not be making.
   */
  insufficient: string | null;
  /**
   * Set when a conclusion IS drawn but its basis is genuinely limited, naming
   * the specific limit in one clause: unconfirmed links, a single capture with
   * no trend, a benchmark that covers a fraction of the catalogue.
   *
   * Declared by the builder rather than inferred by the component, because
   * only the builder knows what its own floor is. `evidence.count` means a
   * different thing on every page (vendors, edges, workflows, models), so a
   * single count threshold in the UI would be an arbitrary rule dressed as a
   * measurement.
   *
   * Where this is set the panel offers the reader their AG Analyst, which is
   * the honest answer to a question the dataset cannot close on its own.
   */
  thin?: string | null;
}

const round1 = (n: number) => Math.round(n * 10) / 10;
const pct = (a: number, b: number) => (b === 0 ? 0 : Math.round((a / b) * 100));

/** Vendors only, never the investors or the services channel. */
export const aiVendors = (m: MarketMetrics): VendorMetrics[] =>
  m.vendors.filter((v) => v.category !== "AI investor");

/** A category leader and how defensible the lead looks. */
export interface CategoryLead {
  category: string;
  leader: string;
  score: number;
  /** The runner-up, so a lead can be described rather than just asserted. */
  runnerUp: string | null;
  gap: number | null;
  /** How many scored vendors the category holds, so a lead of one is visible. */
  contested: number;
}

export interface MarketTake {
  leads: CategoryLead[];
  /** Leads with a runner-up within three points: genuinely open categories. */
  close: CategoryLead[];
  /** Leads clear by ten points or more. */
  clear: CategoryLead[];
  gaining: string[];
  slipping: string[];
  strongButRisky: VendorMetrics[];
}

/**
 * An analyst's read of who is where, named.
 *
 * The insights used to describe the instrument: how to read the table, what
 * the composite does not net off, which columns are comparable. All true, and
 * all of it answered a question the reader had not asked. Somebody arriving at
 * a vendor page wants to know who is ahead and whether the lead means anything,
 * and got a methodology note instead.
 *
 * This computes the substance so the copy can lead with it. The cautions are
 * still carried, underneath, where a caution belongs once the finding is made.
 *
 * Every figure here is read off the scored set. Nothing is inferred about a
 * vendor that carries no score, and a category with one scored vendor reports
 * `runnerUp: null` rather than implying a contest that has one entrant.
 */
export function marketTake(m: MarketMetrics): MarketTake {
  const scored = aiVendors(m).filter((v) => v.composite !== null);

  // THE ASSESSMENT, AND THE MARKETS IT IS SCORED IN.
  //
  // This read overallScore grouped by the vendor record's single `category`
  // field until 17 August 2026. That produced prose about "10 market
  // categories" and a "14.7 point lead" beside a table ranked out of 5 across
  // thirteen markets: the same page describing two different worlds.
  //
  // Both now come from categoryComposites, which is the assessment keyed by
  // market, so the sentence and the table are reading the same numbers. Gaps
  // are on the 0 to 5 scale and are small by comparison: a 0.29 lead in
  // frontier models is the one the comparison calls decisive.
  const nameOf = new Map(m.vendors.map((v) => [v.id, v.name]));
  // Market LABELS, never ids. "workflow_automation_ai" in a sentence a reader
  // is meant to act on is a leaked internal key, and this printed one.
  const labelOf = new Map(MARKET_CATEGORY_LIST.map((c) => [c.id, c.name]));
  const eligible = new Set(scored.map((v) => v.id));

  const leads: CategoryLead[] = [];
  for (const [categoryId, placements] of Object.entries(m.categoryComposites)) {
    const ranked = Object.entries(placements)
      .filter(([vendorId]) => eligible.has(vendorId))
      .sort((a, b) => a[1].rank - b[1].rank);
    if (ranked.length === 0) continue;
    const [topId, top] = ranked[0];
    const second = ranked[1] ?? null;
    leads.push({
      category: labelOf.get(categoryId) ?? categoryId,
      leader: nameOf.get(topId) ?? topId,
      score: top.composite,
      runnerUp: second ? (nameOf.get(second[0]) ?? second[0]) : null,
      // Two decimals: on a 0 to 5 scale a gap rounded to one decimal turns
      // 0.29 into 0.3 and a real separation into a rounding artefact.
      gap: second ? Math.round((top.composite - second[1].composite) * 100) / 100 : null,
      contested: ranked.length,
    });
  }
  // Widest lead first: the most defensible position is the most useful thing
  // to say first, and the closest races are the most useful thing to say last.
  leads.sort((a, b) => (b.gap ?? -1) - (a.gap ?? -1));

  const withRisk = new Set(m.risks.map((r) => r.vendorId));

  return {
    leads,
    // Rescaled with the metric. These were 3 and 10 on a 0 to 100 score; left
    // alone against a 0 to 5 assessment every market would read as "close" and
    // none as "clear", because the widest gap in the set is under one point.
    //
    // 0.15 and 0.50 are the same proportions of the scale the old numbers were
    // of theirs. On today's data that makes frontier models clear at 0.29 and
    // the tightest markets close, which is the reading the comparison gives.
    close: leads.filter((l) => l.gap !== null && l.gap <= 0.15),
    clear: leads.filter((l) => l.gap !== null && l.gap >= 0.5),
    gaining: m.gaining.map((s) => s.vendorName),
    slipping: m.slipping.map((s) => s.vendorName),
    strongButRisky: scored.filter(
      (v) => (v.composite ?? 0) >= 60 && withRisk.has(v.id)
    ),
  };
}

/** "A, B and C", or "A and B", or "A". British English list. */
export function nameList(names: string[], max = 3): string {
  const shown = names.slice(0, max);
  if (shown.length === 0) return "";
  if (shown.length === 1) return shown[0];
  const over = names.length - max;
  // "1 others" shipped once. Singular and plural both matter in copy a reader
  // is meant to trust with figures.
  if (over > 0) {
    return `${shown.join(", ")} and ${over} ${over === 1 ? "other" : "others"}`;
  }
  return `${shown.slice(0, -1).join(", ")} and ${shown[shown.length - 1]}`;
}

function insufficient(
  reason: string,
  sources: string[],
  lane: DataLane
): AnalystInsightData {
  return {
    headline: "",
    summary: "",
    implications: [],
    action: "Monitor",
    news: null,
    evidence: { count: 0, sources, lastUpdated: null, lane },
    insufficient: reason,
  };
}

